local TakeoutVipOrderProductNode = Class('TakeoutVipOrderProductNode')

function TakeoutVipOrderProductNode:__init()
    self.cb = nil
    self.data = nil
    self.handler = nil
end

function TakeoutVipOrderProductNode:__delete()
    self.cb = nil
    self.data = nil
    self.handler = nil
end

function TakeoutVipOrderProductNode:OnDataChangeEvent(id)
    if checkNumber(self.data.id) == checkInt(id) then
        ---当前值，更新装态，提交成功
        self.data.isSubmit = true
        self:FreshUI(self.data)
    end
end

function TakeoutVipOrderProductNode:Awake()
    self.handler = Events.AddListener(Constants.EventNames.EVENT_TAKEOUT_VIP_DATA_CHANGED, Bind(self, self.OnDataChangeEvent))
    SetButtonAction(self.ImgSelect.transform.parent.gameObject, function()
        if self.cb then
            self.cb(self.data)
        end
    end)
end

---FreshUI
---@param data CookOrderDojo
---@param cb function
function TakeoutVipOrderProductNode:FreshUI(data, cb)
    if cb then
        self.cb = cb
    end
    self.data = data
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.needId)
    if data.isSubmit then
        KTool.SetActive(self.StatusComplete.gameObject, true)
        KTool.SetActive(self.GoodNode.gameObject, false)
    else
        KTool.SetActive(self.StatusComplete.gameObject, false)
        KTool.SetActive(self.GoodNode.gameObject, true)
        if goodsVo then
            local env = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
            local no = GoodsUtils.GetThingNo(goodsVo.id)
            local text
            if no >= checkNumber(data.requireNum) then
                --898989
                text = string.format_color_tag(no, "#FFFFFF") .. '/' .. tostring(data.requireNum)
            else
                text = string.format_color_tag(no, "#ff2ea9") .. '/' .. tostring(data.requireNum)
            end

            env:Reload(
                    {
                        goodsId = data.needId,
                        text = text,
                        isShowNo = true
                    }
            )
            env:SetClickButtonAction(function(goodsId)
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(goodsVo) then
                    GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
                end
            end)


            --CfUtils.SetUISwitchImage(self.ImgQuality, checkNumber(goodsVo.quality))
            --CfUtils.FillImage(self.ImgQuality, GoodsUtils.GetFishBgByQualityType(goodsVo.quality))
            --CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
            --[[---<size=46><color=#ff2ea9>8</color></size>/8
            local no = GoodsUtils.GetThingNo(goodsVo.id)
            if no >= checkNumber(data.requireNum) then
                --898989
                self.TextNumber.text = string.format_size_tag(string.format_color_tag(no, "#898989"), 30) .. '/' .. tostring(data.requireNum)
            else
                self.TextNumber.text = string.format_size_tag(string.format_color_tag(no, "#ff2ea9"), 30) .. '/' .. tostring(data.requireNum)
            end]]

        end
    end
end

function TakeoutVipOrderProductNode:OnDestroy()
    if self.handler then
        Events.RemoveListener(Constants.EventNames.EVENT_TAKEOUT_VIP_DATA_CHANGED, self.handler)
    end
    self.handler = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TakeoutVipOrderProductNode